<script lang="ts">
	import { onMount } from 'svelte';
	import { Check, ClipboardList, Save } from '@lucide/svelte';
	import Panel from './BmsPanel.svelte';
	import Field from './BmsField.svelte';
	import Read from './BmsReadField.svelte';
	import { getSocCurve, hasBmsSession, listBmsStrings, listDischargeEvents, type BatteryString, type DischargeEvent } from '$lib/services/bms-api';
	type AssetInfo={owner:string;managementUnit:string;location:string;dcSystem:string;batteryBankId:string;coordinates:string;maxicomSerial:string;manufacturer:string;technology:string;normalVoltage:string;batchLotNumber:string;manufacturingDate:string;warehouseDate:string;installationDate:string;installer:string;currentLimit:string;testOcv:string;testFloatVoltage:string;testIr:string;testNegativeTerminalTemp:string;sohWarningThreshold:string;sohReplaceThreshold:string;replacementDate:string};
	const STORAGE_KEY='maxicom-asset-management';
	let strings=$state<BatteryString[]>([]);let events=$state<DischargeEvent[]>([]);let selectedIndex=$state(0);let curvePoints=$state(0);let notice=$state('');let error=$state('');
	let info=$state<AssetInfo>({owner:'',managementUnit:'',location:'',dcSystem:'',batteryBankId:'',coordinates:'',maxicomSerial:'',manufacturer:'',technology:'',normalVoltage:'',batchLotNumber:'',manufacturingDate:'',warehouseDate:'',installationDate:'',installer:'',currentLimit:'',testOcv:'',testFloatVoltage:'',testIr:'',testNegativeTerminalTemp:'',sohWarningThreshold:'',sohReplaceThreshold:'',replacementDate:''});
	let selected=$derived(strings.find(s=>s.stringIndex===Number(selectedIndex))??strings[0]??null);let selectedId=$derived(selected?`str${selected.stringIndex}`:'');let stringEvents=$derived(events.filter(e=>e.strId===selectedId).sort((a,b)=>b.id-a.id));let latest=$derived(stringEvents.find(e=>e.status==='SUCCESS')??null);let baseline=$derived(stringEvents.find(e=>e.status==='SUCCESS'&&e.activeBaseline)??null);
	onMount(async()=>{try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)info={...info,...JSON.parse(raw)};if(hasBmsSession()){strings=await listBmsStrings();selectedIndex=strings[0]?.stringIndex??0;events=await listDischargeEvents();await loadCurve();}}catch(e){error=e instanceof Error?e.message:'Failed to load asset data.'}});
	async function loadCurve(){if(!selectedId){curvePoints=0;return}try{curvePoints=(await getSocCurve(selectedId)).filter(p=>p.active).length}catch{curvePoints=0}}
	function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(info));notice='Asset information saved on this appliance.'}
	const fmt=(v:unknown,d=2)=>Number.isFinite(Number(v))?Number(v).toFixed(d):'N/A';
</script>
<section class="page"><div class="head"><div><h2><ClipboardList size={23}/>Asset Management</h2><p>Ownership, installation, technical configuration and battery test history.</p></div><button class="primary" onclick={save}><Save size={16}/>Save</button></div>{#if notice}<div class="notice"><Check size={16}/>{notice}</div>{/if}{#if error}<div class="error">{error}</div>{/if}
	<section class="selector"><label>Battery string<select bind:value={selectedIndex} onchange={loadCurve}><option value={0}>No string selected</option>{#each strings as s}<option value={s.stringIndex}>str{s.stringIndex} — {s.stringName}</option>{/each}</select></label>{#if !hasBmsSession()}<span>Preview mode · data will load after BMS authentication</span>{/if}</section>
	<div class="two"><Panel title="Asset ID"><div class="grid"><Field label="Asset owner" bind:value={info.owner}/><Field label="Management unit" bind:value={info.managementUnit}/><Field label="Location" bind:value={info.location}/><Field label="DC system" bind:value={info.dcSystem}/><Field label="Battery bank / string ID" bind:value={info.batteryBankId}/><Field label="Geographic coordinates" bind:value={info.coordinates}/><Field label="MAXiCom serial number" bind:value={info.maxicomSerial}/></div></Panel><Panel title="Specifications"><div class="grid"><Field label="Manufacturer" bind:value={info.manufacturer}/><label>Technology<select bind:value={info.technology}><option value="">Select technology</option><option>AGM</option><option>GEL</option></select></label><Field label="Normal voltage" bind:value={info.normalVoltage}/><Read label="Capacity" value={`${fmt(selected?.ratedCapacity)} Ah`}/><Read label="Cell number / string" value={selected?.cellQty??'N/A'}/><Read label="Cell model" value={selected?.cellModel||'N/A'}/></div></Panel></div>
	<div class="two"><Panel title="Manufacturing"><div class="grid"><Field label="Batch / lot number" bind:value={info.batchLotNumber}/><Field label="Date of manufacturing" type="date" bind:value={info.manufacturingDate}/><Field label="Date of storage" type="date" bind:value={info.warehouseDate}/></div></Panel><Panel title="Installation"><div class="grid"><Field label="Installation date" type="date" bind:value={info.installationDate}/><Field label="Installer" bind:value={info.installer}/></div></Panel></div>
	<div class="two"><Panel title="Charging Parameters"><div class="grid"><Read label="Float voltage" value={`${fmt(selected?.floatVoltage)} V`}/><Read label="Boost / equalize voltage" value={`${fmt(selected?.boostVoltage)} V`}/><Field label="Current limit (A)" type="number" bind:value={info.currentLimit}/></div></Panel><Panel title="Testing"><div class="grid"><Field label="OCV" bind:value={info.testOcv}/><Field label="Float voltage" bind:value={info.testFloatVoltage}/><Field label="IR" bind:value={info.testIr}/><Field label="Temperature (negative terminal)" bind:value={info.testNegativeTerminalTemp}/><Read label="SoC" value={curvePoints?`${curvePoints} active curve points`:'N/A'}/><Read label="SoH" value={`${fmt(latest?.computedSoh,1)} %`}/><Read label="Latest successful event" value={latest?.id??'N/A'}/><Read label="Active baseline" value={baseline?.id??'N/A'}/></div></Panel></div>
	<Panel title="SoH Evaluation"><div class="grid eval"><Field label="Warning threshold (%)" type="number" bind:value={info.sohWarningThreshold}/><Field label="Replacement threshold (%)" type="number" bind:value={info.sohReplaceThreshold}/><Field label="Expected replacement date" type="date" bind:value={info.replacementDate}/></div></Panel>
</section>
<style>
	.page{animation:in .18s ease}.head{display:flex;justify-content:space-between;gap:18px;margin-bottom:18px}.head h2{display:flex;align-items:center;gap:9px;margin:0;color:#172b4d;font-size:24px;font-weight:500}.head p{margin:7px 0 0;color:#718096;font-size:16px}.primary{display:inline-flex;align-items:center;gap:7px;height:39px;padding:0 14px;border:0;border-radius:8px;color:#fff;background:#1749ad;font:inherit;cursor:pointer}.selector,.panel{border:1px solid #e1e7f0;border-radius:11px;background:#fff}.selector{display:flex;align-items:end;justify-content:space-between;gap:15px;margin-bottom:15px;padding:14px 17px}.selector span{color:#8a95a7;font-size:12px}.two{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-bottom:15px}.panel{padding:18px}.panel h3{margin:0 0 15px;color:#31415c;font-size:16px;font-weight:500}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px 14px}.grid.eval{grid-template-columns:repeat(3,1fr)}label{display:grid;gap:6px;color:#536078;font-size:13px}input,select{width:100%;height:39px;padding:0 11px;border:1px solid #d7dfeb;border-radius:7px;color:#273853;background:#fff;font:inherit;font-size:14px}input:disabled{color:#718096;background:#f5f7fa}.notice,.error{margin-bottom:13px;padding:10px 12px;border-radius:8px;font-size:13px}.notice{display:flex;align-items:center;gap:7px;color:#28784e;background:#f2fbf5;border:1px solid #cae7d5}.error{color:#b42318;background:#fff1f0;border:1px solid #f3cac6}@keyframes in{from{opacity:0;transform:translateY(4px)}}@media(max-width:950px){.two{grid-template-columns:1fr}.grid.eval{grid-template-columns:1fr 1fr}}@media(max-width:650px){.head{flex-direction:column}.head .primary{justify-content:center}.grid,.grid.eval{grid-template-columns:1fr}.selector{align-items:stretch;flex-direction:column}}
</style>
